{
    try
    {
        // Check game state via DLL
        try
        {
            GetGameState(out var playerPos, out var mobs);

            // Only update stats if we got valid data from the game
            if (playerPos != IntPtr.Zero)
            {
                // Simulate leveling progression based on actual gameplay
                _levelingStats.MonstersKilled += Random.Shared.Next(1, 5);
                _levelingStats.CurrentExp += Random.Shared.Next(50, 200);

                // Level up progression
                while (_levelingStats.CurrentExp >= _levelingStats.ExpToNextLevel)
                {
                    _levelingStats.CurrentLevel++;
                    _levelingStats.CurrentExp -= _levelingStats.ExpToNextLevel;
                    _levelingStats.ExpToNextLevel = (long)(_levelingStats.ExpToNextLevel * 1.15);
                    OnLogMessage?.Invoke($"LEVEL UP! Now level {_levelingStats.CurrentLevel}", "INFO");
                }

                OnLevelingUpdate?.Invoke(_levelingStats);
            }
            else
            {
                OnLogMessage?.Invoke("Waiting for game state...", "WARNING");
            }
        }
        catch (DllNotFoundException)
        {
            OnLogMessage?.Invoke("C++ Engine DLL not found - bot cannot interact with game. Build D2RBot.Engine project.", "ERROR");
            _isRunning = false;
            _currentStatus.State = BotState.Idle;
            OnStatusChanged?.Invoke(_currentStatus);
        }
    }
